export class VisualItem{
    x: number = 0; // pozicija na gridu
    y: number = 0;
    isVisible: boolean = false;
    color: 'red' | 'blue' = 'red';
    orientation: 'normal' | 'rotated' | 'semi-rotated-left' | 'semi-rotated-right' = 'rotated';
    isTarget: boolean = false;
}
